import { path } from '@servicenow/sdk-build-core'
import * as fs from 'fs'
import { createTestContext } from '../../test-utils'

describe('Transform handling of delete_multiple in Action Definition XML', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    test.skip('Delete entire sys_hub_action_type_definition', async () => {
        const project = ctx.createProject()
        const transformedXMLpath = path.resolve(__dirname, 'delete', 'xmls', 'delete-all.xml')

        project.addFile(path.resolve(__dirname, 'delete', 'action-def.now.ts'))

        const result = await project.transform(transformedXMLpath)

        expect(result.changedFiles.length).toBe(1)

        const content = result.changedFiles[0].getContent()
        expect(content).toBe('')
    })
    test.skip('Action with delete multiple does not remove any non-deleted metadata', async () => {
        const project = ctx.createProject()
        const transformedXMLpath = path.resolve(__dirname, 'delete', 'xmls', 'delete-none.xml')

        project.registerExplicitId('sys_hub_action_type_definition', '7f6d4a28ffbcf6103c50ffffffffff69')
        project.registerCoalesceId(
            'sys_hub_action_output',
            { element: 'flow_array', model: '7f6d4a28ffbcf6103c50ffffffffff69' },
            '66c40e50162b4c97a7c990739cf25bd1'
        )
        project.registerCoalesceId(
            'sys_hub_action_input',
            { element: 'flow_array', model: '7f6d4a28ffbcf6103c50ffffffffff69' },
            'bdcdc268ffbcf6103c50ffffffffff21'
        )
        project.registerCoalesceId(
            'sys_hub_action_input',
            { element: 'flow_object', model: '7f6d4a28ffbcf6103c50ffffffffff69' },
            'fdcdc268ffbcf6103c50ffffffffff1a'
        )

        const flowPath = path.resolve(__dirname, 'delete', 'action-def.now.ts')
        project.addFile(flowPath)

        const result = await project.transform(transformedXMLpath)

        const flowPathResult = path.resolve(__dirname, 'delete', 'results', 'action-def-no-delete.now.ts')
        const expectedContent = fs.readFileSync(flowPathResult, 'utf-8')
        expect(result.changedFiles.length).toBe(1)
        expect(result.changedFiles[0].getContent()).toBe(expectedContent)
    })

    test.skip('delete multiple removes input', async () => {
        const project = ctx.createProject()
        const transformedXMLpath = path.resolve(__dirname, 'delete', 'xmls', 'delete-input.xml')

        project.registerExplicitId('sys_hub_action_type_definition', '7f6d4a28ffbcf6103c50ffffffffff69')
        project.registerCoalesceId(
            'sys_hub_action_output',
            { element: 'flow_array', model: '7f6d4a28ffbcf6103c50ffffffffff69' },
            '66c40e50162b4c97a7c990739cf25bd1'
        )
        project.registerCoalesceId(
            'sys_hub_action_input',
            { element: 'flow_array', model: '7f6d4a28ffbcf6103c50ffffffffff69' },
            'bdcdc268ffbcf6103c50ffffffffff21'
        )
        project.registerCoalesceId(
            'sys_hub_action_input',
            { element: 'flow_object', model: '7f6d4a28ffbcf6103c50ffffffffff69' },
            'fdcdc268ffbcf6103c50ffffffffff1a'
        )
        project.addFile(path.resolve(__dirname, 'delete', 'action-def.now.ts'))

        const result = await project.transform(transformedXMLpath)

        const flowPathResult = path.resolve(__dirname, 'delete', 'results', 'action-def-delete-input.now.ts')
        const expectedContent = fs.readFileSync(flowPathResult, 'utf-8')
        expect(result.changedFiles.length).toBe(1)
        expect(result.changedFiles[0].getContent()).toBe(expectedContent)
    })
})
